static int lowerBound(int *nums, int n, int target) {
  int lo = 0, hi = n;
  while (lo < hi) {
    int mid = lo + (hi - lo) / 2;
    if (nums[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

int *searchRange(int *nums, int numsSize, int target, int *returnSize) {
  *returnSize = 2;
  int *res = (int *)malloc(sizeof(int) * 2);
  int lo = lowerBound(nums, numsSize, target);
  int hi = lowerBound(nums, numsSize, target + 1) - 1;
  if (lo < numsSize && nums[lo] == target) {
    res[0] = lo;
    res[1] = hi;
  } else {
    res[0] = -1;
    res[1] = -1;
  }
  return res;
}

class Solution {
  int lowerBound(vector<int> &nums, int target) {
    int lo = 0, hi = nums.size();
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2;
      if (nums[mid] < target) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

public:
  vector<int> searchRange(vector<int> &nums, int target) {
    int lo = lowerBound(nums, target);
    int hi = lowerBound(nums, target + 1) - 1;
    if (lo < (int)nums.size() && nums[lo] == target) {
      return {lo, hi};
    }
    return {-1, -1};
  }
};

func lowerBound(nums []int, target int) int {
	lo, hi := 0, len(nums)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if nums[mid] < target {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo
}

func searchRange(nums []int, target int) []int {
	lo := lowerBound(nums, target)
	hi := lowerBound(nums, target+1) - 1
	if lo < len(nums) && nums[lo] == target {
		return []int{lo, hi}
	}
	return []int{-1, -1}
}

class Solution {
  private int lowerBound(int[] nums, int target) {
    int lo = 0, hi = nums.length;
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2;
      if (nums[mid] < target) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

  public int[] searchRange(int[] nums, int target) {
    int lo = lowerBound(nums, target);
    int hi = lowerBound(nums, target + 1) - 1;
    if (lo < nums.length && nums[lo] == target) {
      return new int[] { lo, hi };
    }
    return new int[] { -1, -1 };
  }
}

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def lower_bound(t: int) -> int:
            lo, hi = 0, len(nums)
            while lo < hi:
                mid = (lo + hi) // 2
                if nums[mid] < t:
                    lo = mid + 1
                else:
                    hi = mid
            return lo

        lo = lower_bound(target)
        hi = lower_bound(target + 1) - 1
        if lo < len(nums) and nums[lo] == target:
            return [lo, hi]
        return [-1, -1]

impl Solution {
  fn lower_bound(nums: &[i32], target: i32) -> usize {
    let (mut lo, mut hi) = (0usize, nums.len());
    while lo < hi {
      let mid = lo + (hi - lo) / 2;
      if nums[mid] < target {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    lo
  }

  pub fn search_range(nums: Vec<i32>, target: i32) -> Vec<i32> {
    let lo = Solution::lower_bound(&nums, target);
    if lo < nums.len() && nums[lo] == target {
      let hi = Solution::lower_bound(&nums, target + 1) as i32 - 1;
      return vec![lo as i32, hi];
    }
    vec![-1, -1]
  }
}

const searchRange = (nums: number[], target: number): number[] => {
  const lowerBound = (t: number): number => {
    let lo = 0;
    let hi = nums.length;
    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (nums[mid] < t) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  };

  const lo = lowerBound(target);
  const hi = lowerBound(target + 1) - 1;
  if (lo < nums.length && nums[lo] === target) return [lo, hi];
  return [-1, -1];
};
